fn gcd_calc(m: u32, n: u32) -> u32 {
    debug_assert!(m > 0 && n > 0);

    // Euclidean algorithm via repeated remainder.
    // Invariant: gcd(a, b) == gcd(m, n). Also, a > 0 and b > 0 throughout the loop.
    let mut a = m;
    let mut b = n;

    while b != 0 {
        let r = a % b; // 0 <= r < b
        a = b;
        b = r;
    }

    // If inputs are strictly positive, the final gcd is positive.
    a
}